import{_ as t,c as a,o as r,ag as n}from"./chunks/framework.CMajxlqO.js";const h=JSON.parse('{"title":"Siemens S7-1200 PLC-system","description":"","frontmatter":{},"headers":[],"relativePath":"01-introduktion/s7-1200-plc-system.md","filePath":"01-introduktion/s7-1200-plc-system.md","lastUpdated":1768472766000}'),i={name:"01-introduktion/s7-1200-plc-system.md"};function o(s,e,l,d,m,g){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="siemens-s7-1200-plc-system" tabindex="-1">Siemens S7-1200 PLC-system <a class="header-anchor" href="#siemens-s7-1200-plc-system" aria-label="Permalink to &quot;Siemens S7-1200 PLC-system&quot;">​</a></h1><p>SIMATIC S7-1200 är Siemens kompakta PLC-familj designad för små till medelstora automationslösningar. S7-1200 erbjuder hög prestanda och flexibilitet i ett kostnadseffektivt paket, perfekt för maskinstyrning och processautomation.</p><h2 id="oversikt-s7-1200-familjen" tabindex="-1">Översikt S7-1200 familjen <a class="header-anchor" href="#oversikt-s7-1200-familjen" aria-label="Permalink to &quot;Översikt S7-1200 familjen&quot;">​</a></h2><h3 id="huvudkomponenter" tabindex="-1">Huvudkomponenter <a class="header-anchor" href="#huvudkomponenter" aria-label="Permalink to &quot;Huvudkomponenter&quot;">​</a></h3><p>S7-1200 systemet består av:</p><ul><li><strong>CPU</strong> - Centralenheten med processor, minne och inbyggda I/O</li><li><strong>Signal Modules (SM)</strong> - Tilläggsmoduler för digitala och analoga signaler</li><li><strong>Signal Boards (SB)</strong> - Kompakta moduler som monteras direkt på CPU:n</li><li><strong>Communication Modules (CM)</strong> - För utökad kommunikation (RS232, RS485, etc.)</li><li><strong>SIMATIC HMI</strong> - Operatörspaneler för visualisering</li></ul><h3 id="cpu-varianter" tabindex="-1">CPU-varianter <a class="header-anchor" href="#cpu-varianter" aria-label="Permalink to &quot;CPU-varianter&quot;">​</a></h3><p>S7-1200 finns i flera CPU-varianter:</p><table tabindex="0"><thead><tr><th>CPU</th><th>Arbetsminne</th><th>Integrerade I/O</th><th>Expanderbarhet</th></tr></thead><tbody><tr><td>CPU 1211C</td><td>50 KB</td><td>6 DI / 4 DQ / 2 AI</td><td>3 moduler</td></tr><tr><td>CPU 1212C</td><td>75 KB</td><td>8 DI / 6 DQ / 2 AI</td><td>8 moduler</td></tr><tr><td>CPU 1214C</td><td>125 KB</td><td>14 DI / 10 DQ / 2 AI</td><td>8 moduler</td></tr><tr><td>CPU 1215C</td><td>150 KB</td><td>14 DI / 10 DQ / 2 AI / 2 AO</td><td>8 moduler</td></tr><tr><td>CPU 1217C</td><td>150 KB</td><td>10 DI / 8 DQ / 2 AI / 2 AO</td><td>8 moduler</td></tr></tbody></table><h2 id="tekniska-specifikationer" tabindex="-1">Tekniska specifikationer <a class="header-anchor" href="#tekniska-specifikationer" aria-label="Permalink to &quot;Tekniska specifikationer&quot;">​</a></h2><h3 id="prestanda" tabindex="-1">Prestanda <a class="header-anchor" href="#prestanda" aria-label="Permalink to &quot;Prestanda&quot;">​</a></h3><ul><li><strong>Cykeltid:</strong> Snabb exekvering (typiskt &lt; 0.1 ms för 1000 instruktioner)</li><li><strong>Kommunikation:</strong> Profinet, Ethernet TCP/IP, Modbus TCP</li><li><strong>Programminne:</strong> 50-150 KB arbetsminne beroende på CPU</li><li><strong>Dataminne:</strong> 50-100 KB remanent minne</li><li><strong>Matningsspänning:</strong> 24V DC eller 85-264V AC (beroende på modell)</li></ul><h3 id="integrerade-funktioner" tabindex="-1">Integrerade funktioner <a class="header-anchor" href="#integrerade-funktioner" aria-label="Permalink to &quot;Integrerade funktioner&quot;">​</a></h3><ul><li><strong>Pulsutgångar</strong> - För stegmotorstyrning och hastighetsreglering (upp till 100 kHz)</li><li><strong>Höghastighetsingångar</strong> - Räknare och frekvensmätning</li><li><strong>PID-reglering</strong> - Inbyggda PID-funktioner för processreglering</li><li><strong>Motion Control</strong> - Grundläggande positionering (med teknologiobjekt)</li><li><strong>Webbserver</strong> - För diagnostik och övervakning via webbläsare</li></ul><h2 id="programmeringsmiljo" tabindex="-1">Programmeringsmiljö <a class="header-anchor" href="#programmeringsmiljo" aria-label="Permalink to &quot;Programmeringsmiljö&quot;">​</a></h2><p>S7-1200 programmeras i <strong>TIA Portal</strong> med STEP 7 Basic eller Professional:</p><h3 id="programmeringssprak" tabindex="-1">Programmeringsspråk <a class="header-anchor" href="#programmeringssprak" aria-label="Permalink to &quot;Programmeringsspråk&quot;">​</a></h3><ul><li><strong>LAD (Ladder Diagram)</strong> - Stegdiagram, populärt i industrin</li><li><strong>FBD (Function Block Diagram)</strong> - Funktionsblockschema</li><li><strong>SCL (Structured Control Language)</strong> - Textbaserat språk liknande Pascal</li></ul><h3 id="minnesomraden" tabindex="-1">Minnesområden <a class="header-anchor" href="#minnesomraden" aria-label="Permalink to &quot;Minnesområden&quot;">​</a></h3><ul><li><strong>I (Input)</strong> - Ingångssignaler från sensorer</li><li><strong>Q (Output)</strong> - Utgångssignaler till aktuatorer</li><li><strong>M (Memory)</strong> - Internminne för mellanresultat</li><li><strong>DB (Data Blocks)</strong> - Strukturerad datalagring</li></ul><h2 id="applikationsomraden" tabindex="-1">Applikationsområden <a class="header-anchor" href="#applikationsomraden" aria-label="Permalink to &quot;Applikationsområden&quot;">​</a></h2><p>S7-1200 används i många olika branscher:</p><ul><li>Maskinstyrning och förpackningsmaskiner</li><li>Transportband och material handling</li><li>Byggautomation (HVAC, belysning)</li><li>Vattenrening och processtyrning</li><li>Små produktionslinjer</li></ul><h2 id="resurser-och-dokumentation" tabindex="-1">Resurser och dokumentation <a class="header-anchor" href="#resurser-och-dokumentation" aria-label="Permalink to &quot;Resurser och dokumentation&quot;">​</a></h2><h3 id="officiella-dokument" tabindex="-1">Officiella dokument <a class="header-anchor" href="#officiella-dokument" aria-label="Permalink to &quot;Officiella dokument&quot;">​</a></h3><ul><li><a href="https://support.industry.siemens.com/cs/document/36912030/simatic-s7-1200-system-manual?dti=0&amp;lc=en-WW" target="_blank" rel="noreferrer">S7-1200 System Manual</a> - Komplett systemdokumentation</li><li><a href="https://support.industry.siemens.com/cs/products?search=s7-1200%20getting%20started" target="_blank" rel="noreferrer">Siemens: S7-1200 Getting Started</a> - Nybörjarguider</li><li><a href="https://support.industry.siemens.com/cs/ww/en/view/90885040" target="_blank" rel="noreferrer">S7-1200 Programming Guideline</a> - Best practices för programmering</li></ul><h3 id="video-tutorials" tabindex="-1">Video-tutorials <a class="header-anchor" href="#video-tutorials" aria-label="Permalink to &quot;Video-tutorials&quot;">​</a></h3><ul><li>Sök på YouTube: &quot;Siemens S7-1200 tutorial&quot; för omfattande videogenomgångar</li><li><a href="https://www.youtube.com/@SiemensIndustry" target="_blank" rel="noreferrer">SLIO Academy</a> - Siemens officiella YouTube-kanal</li></ul><h3 id="katalog-och-datablad" tabindex="-1">Katalog och datablad <a class="header-anchor" href="#katalog-och-datablad" aria-label="Permalink to &quot;Katalog och datablad&quot;">​</a></h3><ul><li><a href="https://mall.industry.siemens.com/mall/en/WW/Catalog/Products/10345783" target="_blank" rel="noreferrer">SIMATIC S7-1200 Catalog</a> - Produktkatalog med tekniska data</li></ul><div class="tip custom-block"><p class="custom-block-title">Tips för nybörjare</p><p>Börja med CPU 1214C - den har bra balans mellan pris, prestanda och I/O-kapacitet för de flesta lärandeprojekt.</p></div>',31)])])}const c=t(i,[["render",o]]);export{h as __pageData,c as default};
